import { clsx, type ClassValue } from "clsx";
import { extendTailwindMerge } from "tailwind-merge";

const twMerge = extendTailwindMerge({
  extend: { theme: { radius: ["control", "surface", "overlay"], shadow: ["overlay"] } },
});

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

import type { ComponentProps, ReactNode } from "react";
import { cn } from "./lib/cn";
import "./separator.css";

export type SeparatorProps = Omit<ComponentProps<"div">, "children"> & {
  orientation?: "horizontal" | "vertical";
  /** Decoration only: hidden from assistive technology. Set false when the line divides regions people navigate between. */
  decorative?: boolean;
  /** A darker line, for dividing unrelated areas. */
  strong?: boolean;
  /** Indents a horizontal line from both edges, to sit between rows of a list. */
  inset?: boolean;
  /** Text in the line, such as "or continue with email". Horizontal only. */
  label?: ReactNode;
};

/**
 * A 1px divider in the same hairline the toolbar and dock draw. It is decoration by
 * default, so screen readers are not told about it; a labelled one is a real separator
 * with that text as its name.
 */
export function Separator({
  orientation = "horizontal",
  decorative = true,
  strong,
  inset,
  label,
  className,
  ...props
}: SeparatorProps) {
  if (label !== undefined && orientation === "horizontal") {
    return (
      <div
        data-slot="separator-labelled"
        role="separator"
        aria-orientation="horizontal"
        className={className}
        {...props}
      >
        {label}
      </div>
    );
  }
  return (
    <div
      data-slot="separator"
      data-orientation={orientation}
      data-strong={strong || undefined}
      data-inset={inset || undefined}
      role={decorative ? "none" : "separator"}
      aria-orientation={decorative ? undefined : orientation}
      className={cn(className)}
      {...props}
    />
  );
}

/* separator.tsx's styles; it imports this file. Edit freely. */
@layer theme, base, components, utilities;

@layer components {
  /* Separator: the toolbar's 1px hairline, standalone. */
  [data-slot="separator"] { flex: none; background: var(--border); }
  [data-slot="separator"][data-orientation="horizontal"] { width: 100%; height: 1px; }
  [data-slot="separator"][data-orientation="vertical"] { align-self: stretch; width: 1px; min-height: 16px; }
  [data-slot="separator"][data-strong] { background: var(--border-strong); }
  [data-slot="separator"][data-inset] { width: auto; margin-inline: 16px; }
  [data-slot="separator-labelled"] { display: flex; align-items: center; gap: 12px; width: 100%; color: var(--muted-foreground); font-size: 12px; line-height: 18px; }
  [data-slot="separator-labelled"]::before, [data-slot="separator-labelled"]::after { content: ""; flex: 1; height: 1px; background: var(--border); }
}
